css:
.hidden-pdf{display:none !important;}
/* Enterprise Quotation - Class A - OM | Sprint 2 fine-tune | all rules scoped under .eqa */
.eqa{--ink:#141414;--soft:#43484d;--faint:#6b7075;--rule:#c2c6ca;--hair:#e4e7ea;--band:#eef1f4;--zebra:#f7f8f9;--navy:#0b3d62;--warnbg:#fdf6e6;--warnink:#8a5a00;--stopbg:#fbeceb;--stopink:#a02020;--infobg:#eef4f9;--infoink:#0b3d62;
font-family:Arial,Helvetica,"Liberation Sans",sans-serif;color:var(--ink);font-size:9pt;line-height:1.42;orphans:3;widows:3;-webkit-print-color-adjust:exact;print-color-adjust:exact;}
.eqa *{box-sizing:border-box;}
.eqa p{margin:0 0 2.2mm 0;orphans:3;widows:3;}
.eqa b{font-weight:700;}
.eqa .vh{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;}

.eqa .pg{padding-bottom:2mm;}
.eqa .pg + .pg{break-before:page;page-break-before:always;}

.eqa .alert{display:flex;flex-direction:column;gap:.6mm;border-left:2.4pt solid;padding:2mm 3mm;margin:0 0 2.6mm 0;font-size:8pt;break-inside:avoid;page-break-inside:avoid;}
.eqa .alert b{letter-spacing:.04em;}
.eqa .alert.stop{background:var(--stopbg);border-color:var(--stopink);color:var(--stopink);}
.eqa .alert.warn{background:var(--warnbg);border-color:var(--warnink);color:var(--warnink);}
.eqa .alert.info{background:var(--infobg);border-color:var(--infoink);color:var(--infoink);}
.eqa .alert span{color:var(--soft);}

/* S2-01 | one consolidated diagnostic panel replaces four stacked panels.
   Same palette, same semantics, ~1/3 of the vertical cost. */
.eqa .alert.dx{gap:.9mm;padding:2mm 3mm;margin-bottom:3.4mm;}
.eqa .alert.dx b{font-size:8.2pt;}
.eqa .alert.dx span{display:block;font-size:7.5pt;line-height:1.38;color:var(--soft);}
.eqa .alert.dx span i{font-style:normal;font-weight:700;letter-spacing:.05em;margin-right:2mm;white-space:nowrap;}
.eqa .alert.stop.dx span i{color:var(--stopink);}
.eqa .alert.info.dx span i{color:var(--infoink);}

.eqa .doctitle{font-size:16pt;font-weight:700;letter-spacing:.005em;color:var(--navy);margin:1.5mm 0 4mm 0;line-height:1.2;}

/* S3-01 | metadata panel: label/value pairs on a shared baseline grid, hairline
   separators instead of dotted leaders, no field-box appearance */
.eqa .meta{display:grid;grid-template-columns:1fr 1fr;gap:0 12mm;border-top:.7pt solid var(--rule);border-bottom:.7pt solid var(--rule);padding:3.2mm 0 3mm 0;margin-bottom:4.5mm;break-inside:avoid;page-break-inside:avoid;}
.eqa .mrow{display:grid;grid-template-columns:auto 1fr;align-items:baseline;column-gap:6mm;padding:1.5mm 0 1.7mm 0;border-bottom:.4pt solid var(--hair);}
.eqa .meta .mrow:nth-last-child(1),.eqa .meta .mrow:nth-last-child(2){border-bottom:0;padding-bottom:0;}
.eqa .mrow span{font-size:7.8pt;font-weight:400;letter-spacing:.07em;text-transform:uppercase;color:var(--faint);white-space:nowrap;}
.eqa .mrow b{font-size:9.2pt;font-weight:700;color:var(--ink);text-align:right;letter-spacing:.01em;font-variant-numeric:tabular-nums;font-feature-settings:"tnum" 1;}

.eqa .sec{margin:0 0 3.2mm 0;}
.eqa .sh{font-size:8.4pt;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--navy);
border-bottom:.7pt solid var(--rule);padding-bottom:1.1mm;margin-bottom:2mm;break-after:avoid;page-break-after:avoid;}
.eqa .pn{font-size:11pt;font-weight:700;line-height:1.3;}
.eqa .pl{font-size:9pt;}
.eqa .pf{color:var(--faint);font-size:8.4pt;}
.eqa .subj{font-size:10pt;font-weight:700;line-height:1.35;background:var(--band);padding:2.4mm 3mm;border-left:2.4pt solid var(--navy);}
.eqa .note{font-size:8pt;color:var(--faint);}
.eqa .rt{font-size:8.8pt;}
.eqa .rt.small{font-size:8pt;}

.eqa .sign{margin-top:11mm;break-inside:avoid;page-break-inside:avoid;}
.eqa .sigline{width:62mm;border-bottom:.7pt solid var(--ink);height:0;margin-bottom:1.6mm;}

.eqa table.tbl{width:100%;border-collapse:collapse;font-size:8.6pt;table-layout:fixed;}
.eqa table.tbl caption{text-align:left;}
.eqa table.tbl thead{display:table-header-group;}
.eqa table.tbl tfoot{display:table-footer-group;}
.eqa table.tbl th{background:var(--band);border-top:.7pt solid var(--rule);border-bottom:.7pt solid var(--rule);
padding:1.5mm 2mm;text-align:left;font-size:8pt;letter-spacing:.05em;text-transform:uppercase;color:var(--navy);}
.eqa table.tbl td{border-bottom:.35pt solid var(--rule);padding:1.4mm 2mm;vertical-align:top;overflow-wrap:break-word;word-wrap:break-word;}
.eqa table.tbl tbody tr:nth-child(even) td{background:var(--zebra);}
.eqa table.tbl tbody tr{break-inside:avoid;page-break-inside:avoid;}
/* S8-B | column widths rebalanced. Content width is unchanged (A4 minus the
   frozen 12mm side margins = 186mm); only the split between columns moves.
   Fixed columns: 9 + 11 + 12 + 26 + 28 = 86mm, so Description resolves to
   ~100mm - by far the widest column, up ~2mm. #, UoM and Qty keep their
   original widths so "10" and short units such as "Nos" never wrap. Rate and Amount keep room for a
   14-character currency string at 8.6pt tabular figures, so numeric
   readability is not compromised. No clamp, no ellipsis, no max-height:
   the Description cell wraps naturally over as many lines as it needs. */
.eqa .c-n{width:9mm;text-align:right;}
.eqa .c-d{width:auto;}
/* UoM column removed from the priced schedule; the freed width is absorbed
   by the auto-width Description column under the fixed table layout. */
.eqa .c-q{width:12mm;text-align:right;}
.eqa .c-r{width:26mm;text-align:right;}
.eqa .c-a{width:28mm;text-align:right;}
.eqa .c-r,.eqa .c-a,.eqa .c-q{font-variant-numeric:tabular-nums;}
.eqa .idesc{font-weight:700;line-height:1.3;}
.eqa .icode,.eqa .iref{font-size:7.6pt;line-height:1.3;color:var(--faint);}
.eqa .cont{font-size:7.8pt;color:var(--faint);border-bottom:0;padding:1mm 2mm;}

.eqa .totwrap{display:flex;justify-content:flex-end;margin-top:2.6mm;break-inside:avoid;page-break-inside:avoid;}
.eqa table.tot{border-collapse:collapse;font-size:9pt;min-width:84mm;}
.eqa table.tot td{padding:1.2mm 2mm;border-bottom:.35pt solid var(--rule);}
.eqa table.tot td:last-child{text-align:right;width:36mm;font-variant-numeric:tabular-nums;}
/* S2-04 | Total Payable is the strongest element on the commercial page */
.eqa table.tot tr.grand td{border-top:1.6pt solid var(--navy);border-bottom:1.6pt solid var(--navy);
background:var(--navy);color:#fff;font-weight:700;font-size:11.5pt;letter-spacing:.01em;padding:2.2mm 2mm;}
.eqa .inwords{margin-top:1.6mm;font-size:8.4pt;background:var(--zebra);border-left:2.4pt solid var(--rule);padding:1.4mm 3mm;break-inside:avoid;page-break-inside:avoid;}
.eqa .inwords span{color:var(--faint);text-transform:uppercase;letter-spacing:.06em;font-size:7.9pt;display:block;}

.eqa .gr2{display:grid;grid-template-columns:1fr 1fr;gap:0 6mm;}
/* S4-01 | conditions rows adopt the metadata hairline family (was .35pt dotted) */
.eqa .kv{display:flex;gap:3mm;padding:1.1mm 0 1.2mm 0;border-bottom:.4pt solid var(--hair);font-size:8.6pt;}
.eqa .kv span{flex:0 0 22mm;color:var(--faint);}
.eqa .kv b{flex:1 1 auto;font-weight:700;}
.eqa .gr2 > div > .kv:last-child{border-bottom:0;padding-bottom:0;}
/* S7-01 | pagination: hold the contractual section together when it fits a page */
.eqa .sec.tc-hold{break-inside:avoid;page-break-inside:avoid;}

.eqa .acc{margin-top:2mm;break-inside:avoid;page-break-inside:avoid;}
.eqa .accl{font-size:7.9pt;color:var(--faint);text-transform:uppercase;letter-spacing:.06em;margin-top:2.2mm;}
.eqa .accr{border-bottom:.7pt solid var(--ink);height:5mm;}
.eqa .acc .gr2 > div > .accl:first-child{margin-top:0;}

/* S2-05 | Annexure pagination.
   The intro is glued to item 1, so the annexure can no longer open on a page of
   its own; and a spec taller than one page is allowed to break internally
   instead of being pushed whole onto the next page. */
.eqa .annex .anx-intro{break-after:avoid;page-break-after:avoid;break-inside:avoid;page-break-inside:avoid;margin-bottom:3.4mm;}
.eqa .annex .spec{margin-bottom:4.2mm;break-inside:auto;page-break-inside:auto;}
.eqa .spec-h{font-size:9.4pt;font-weight:700;line-height:1.35;background:var(--band);padding:1.8mm 2.5mm;margin-bottom:1.6mm;
break-after:avoid;page-break-after:avoid;break-inside:avoid;page-break-inside:avoid;}
.eqa .spec-sh{font-size:7.9pt;color:var(--faint);text-transform:uppercase;letter-spacing:.06em;margin:2.2mm 0 1.2mm 0;break-after:avoid;page-break-after:avoid;}
.eqa ul.speclist{margin:0;padding-left:5mm;font-size:8.4pt;}
.eqa ul.speclist li{margin-bottom:1mm;orphans:3;widows:3;}

.eqa .hardfail{border:1.2pt solid var(--stopink);background:var(--stopbg);padding:8mm;color:var(--stopink);}
.eqa .hf-h{font-size:13pt;font-weight:700;letter-spacing:.05em;margin-bottom:4mm;}
.eqa .hardfail p{color:var(--ink);font-size:9.4pt;}
.eqa .hf-f{font-size:8pt;color:var(--faint);margin-top:5mm;}

/* D-16 correction | normal-flow document control strips replace the fixed repeating footer */
.eqa .ctrlstrip{border-top:.7pt solid var(--rule);padding-top:1.6mm;margin-top:4mm;margin-bottom:4mm;
font-size:8pt;letter-spacing:.02em;color:var(--faint);background:#fff;}
.eqa .ctrlstrip.ctrl-end{margin-top:5mm;margin-bottom:0;break-inside:avoid;page-break-inside:avoid;}
/* D-05 correction | column widths when the milestone label column is suppressed */
/* S2-07 | the payment schedule carries different semantics to the priced schedule,
   so it keeps its own column widths under the fixed table layout */
.eqa table.tbl.pay .c-q{width:22mm;}
.eqa table.tbl.pay .c-r{width:32mm;}
.eqa table.tbl.pay .c-a{width:32mm;}
.eqa table.tbl.pay.ps-nolabel .c-r{width:auto;}
/* S5 | printed block notice: one heading line, nothing else. */

/* S14 | company-name watermark REMOVED on instruction. The former
   .eqa.eqa-wm tiled background rule is deleted; nothing replaces it. */

/* S2-13 | FINAL POLISH PASS - presentation only, no content change.
   F1  The metadata panel already closes with its own bottom rule. The page-1
       confidentiality strip then drew a second parallel hairline 4.5mm below
       it with nothing in between, reading as a duplicated rule. Suppress the
       strip rule only where the strip directly follows the panel; the closing
       .ctrl-end strip keeps its rule because it separates real content.
   F2  Priced-schedule numeric headers were left-aligned while their values are
       right-aligned, so Qty / Rate / Amount headings sat away from their
       figures. Align the headers to their own columns. No height change.
   F3  .inwords carried a top margin but no bottom margin, so whenever a
       section follows it on the same page its heading touched the panel.
       Adopt the standard .sec bottom rhythm (3.2mm). */
.eqa .meta + .ctrlstrip{border-top:0;}
.eqa table.tbl thead th.c-n,.eqa table.tbl thead th.c-q,.eqa table.tbl thead th.c-r,.eqa table.tbl thead th.c-a{text-align:right;}
.eqa .inwords{margin-bottom:3.2mm;}


/* S2-14 FINAL POLISH (pre-freeze) */
/* 1. Priced schedule: description body to regular weight (single undifferentiated source block; no heading markup present to preserve). Size, line-height, widths, wording unchanged. */
.eqa .idesc{font-weight:400;}
/* 2. Metadata separators: parity-safe. Grid is row-major, 2 columns. Rule drawn as border-top between rows, suppressed on the first visual row and on a lone trailing cell (odd row count), so no half-width orphan rule can appear. Outer .meta top/bottom rules, typography, columns and padding preserved. */
.eqa .meta .mrow{border-bottom:0;border-top:.4pt solid var(--hair);}
.eqa .meta .mrow:nth-child(-n+2){border-top:0;}
.eqa .meta .mrow:last-child:nth-child(odd){border-top:0;}
/* :nth-child(n) is a specificity bump only, so the parity-aware padding below overrides the older nth-last-child pair */
.eqa .meta .mrow:nth-child(n){padding-bottom:1.7mm;}
.eqa .meta .mrow:last-child,.eqa .meta .mrow:nth-last-child(2):nth-child(odd){padding-bottom:0;}

/* S2-15 PAGE-3 SECTION RHYTHM — scoped to the Scope / Commercial Conditions / Payment Terms run only (sections following the amount-in-words block). Global .sec margin, page 1 and Contractual Terms internals untouched. */
/* S2-16 supersedes the positional selectors above: the same values now belong to the sections themselves, so an absent section cannot transfer its spacing to another. */
.eqa .scope-sec{margin-bottom:5.5mm;}
.eqa .commercial-sec{margin-bottom:4.5mm;}
.eqa .payment-sec{margin-bottom:5.5mm;}


/* S2-17 | CONTRACTUAL TERMS READABILITY TEST -------------------------------
   Isolated legibility test of the contractual clause body and the bold clause
   headings only. Scoped strictly to the Contractual Terms section via .sec.tc
   so no other .rt, .small, schedule header, control strip or footer text is
   affected. Line-height is pinned to the document base ratio of 1.42, which is
   the value the section already resolved to, so only the type size changes. */
.eqa .sec.tc .rt.small{font-size:8.5pt;line-height:1.42;}


/* S11 | ADAPTIVE PAGINATION -------------------------------------------------
   Architecture only. No typography, colour, width, margin-geometry or identity
   change. Three rules:
   1. Secondary description content that does not qualify for Annexure A stays
      in the priced-schedule Description cell. It inherits .idesc exactly
      (8.6pt, weight 400, natural wrapping) and receives only a small block
      separation, so a continuation line is visually identical to the primary
      description line. No faint metadata treatment is applied, because the
      source does not reliably distinguish a reference such as a serial number
      from ordinary continuation prose.
   2. Annexure A is a content section, not a page identity. The forced page
      wrapper was removed from the markup, so the Annexure now consumes
      available space when it is small and moves to the next page only when it
      genuinely does not fit. This rule restores the normal section rhythm
      above it, which the removed page wrapper used to provide.
   3. Each Contractual Terms clause is protected from splitting. Combined with
      the existing heading break-after:avoid and the guarded section hold, a
      terms section taller than one page now fragments at clause boundaries
      instead of being pushed whole onto a page it can never fill. This is the
      structural guarantee that no blank or throwaway page can be produced. */
.eqa .idesc-cont{margin-top:.8mm;}
.eqa .annex{margin-top:5.5mm;}
.eqa .sec.tc .rt > *{break-inside:avoid;page-break-inside:avoid;}

/* S12 ANNEXURE MINIMUM-START (generic, content-adaptive).
   Purpose: prevent an Annexure item from starting at the very bottom of a
   page with only its heading / key-value rows and no meaningful
   specification content. Chains break-after:avoid from the item heading
   through the key-value rows, the sub-heading and the first specification
   entries, so Chrome must move the whole start group forward if it does not
   fit. Purely CSS-native: no document identity, no page-number test, no
   item-count test, no forced Annexure page break, no min-height, no spacer.
   Entries beyond the protected start group paginate naturally, and an
   Annexure larger than one page can still break internally. */
.eqa .annex .kv{break-after:avoid;page-break-after:avoid;break-inside:avoid;page-break-inside:avoid;}
.eqa .annex ul.speclist > li{break-inside:avoid;page-break-inside:avoid;}
.eqa .annex ul.speclist > li:nth-child(-n+2){break-after:avoid;page-break-after:avoid;}


/* ===== WK-COMPAT LAYER (additive, appended) ===== */
/* 1. literal-colour re-declarations: engine has no CSS custom properties */
.eqa{color:#141414;}
.eqa .mast{border-bottom:2pt solid #0b3d62;}
.eqa .ent{color:#0b3d62;}
.eqa .entl{color:#43484d;}
.eqa .entc{color:#141414;}
.eqa .alert.stop{background:#fbeceb;border-color:#a02020;color:#a02020;}
.eqa .alert.warn{background:#fdf6e6;border-color:#8a5a00;color:#8a5a00;}
.eqa .alert.info{background:#eef4f9;border-color:#0b3d62;color:#0b3d62;}
.eqa .alert span{color:#43484d;}
.eqa .alert.dx span{color:#43484d;}
.eqa .alert.stop.dx span i{color:#a02020;}
.eqa .alert.info.dx span i{color:#0b3d62;}
.eqa .doctitle{color:#0b3d62;}
.eqa .meta{border-top:.7pt solid #c2c6ca;border-bottom:.7pt solid #c2c6ca;}
.eqa .mrow{border-bottom:.4pt solid #e4e7ea;}
.eqa .mrow span{color:#6b7075;}
.eqa .mrow b{color:#141414;}
.eqa .sh{color:#0b3d62;border-bottom:.7pt solid #c2c6ca;}
.eqa .pf{color:#6b7075;}
.eqa .subj{background:#eef1f4;border-left:2.4pt solid #0b3d62;}
.eqa .note{color:#6b7075;}
.eqa .sigline{border-bottom:.7pt solid #141414;}
.eqa table.tbl th{background:#eef1f4;border-top:.7pt solid #c2c6ca;border-bottom:.7pt solid #c2c6ca;color:#0b3d62;}
.eqa table.tbl td{border-bottom:.35pt solid #c2c6ca;}
.eqa table.tbl tbody tr:nth-child(even) td{background:#f7f8f9;}
.eqa .icode,.eqa .iref{color:#6b7075;}
.eqa .cont{color:#6b7075;}
.eqa table.tot td{border-bottom:.35pt solid #c2c6ca;}
.eqa table.tot tr.grand td{border-top:1.6pt solid #0b3d62;border-bottom:1.6pt solid #0b3d62;background:#0b3d62;}
.eqa .inwords{background:#f7f8f9;border-left:2.4pt solid #c2c6ca;}
.eqa .inwords span{color:#6b7075;}
.eqa .kv{border-bottom:.4pt solid #e4e7ea;}
.eqa .kv span{color:#6b7075;}
.eqa .accl{color:#6b7075;}
.eqa .accr{border-bottom:.7pt solid #141414;}
.eqa .spec-h{background:#eef1f4;}
.eqa .spec-sh{color:#6b7075;}
.eqa .hardfail{border:1.2pt solid #a02020;background:#fbeceb;color:#a02020;}
.eqa .hardfail p{color:#141414;}
.eqa .hf-f{color:#6b7075;}
.eqa .ctrlstrip{border-top:.7pt solid #c2c6ca;color:#6b7075;}
.eqa .meta .mrow{border-top:.4pt solid #e4e7ea;}

/* 2. table-model layout fallbacks */
/* WK-COMPAT | additive engine-compatibility layer. Base rules use the CSS table model,
   which the wkhtmltopdf engine supports; the @supports block re-asserts the approved
   grid/flex design for Chrome, which wkhtmltopdf skips. No approved rule is edited. */
.eqa .mast{display:table;width:100%;}
.eqa .mast-l{display:table-cell;width:52mm;vertical-align:top;}
.eqa .mast-r{display:table-cell;vertical-align:top;text-align:right;}
.eqa .mrow{display:table;width:100%;}
.eqa .mrow>span{display:table-cell;vertical-align:baseline;padding-right:6mm;white-space:nowrap;}
.eqa .mrow>b{display:table-cell;vertical-align:baseline;width:100%;}
.eqa .gr2{display:table;width:100%;table-layout:fixed;border-spacing:0;}
.eqa .gr2>div{display:table-cell;vertical-align:top;}
.eqa .gr2>div:first-child{padding-right:3mm;}
.eqa .gr2>div+div{padding-left:3mm;}
.eqa .kv{display:table;width:100%;}
.eqa .kv>span{display:table-cell;width:22mm;vertical-align:top;padding-right:3mm;}
.eqa .kv>b{display:table-cell;vertical-align:top;}
.eqa .totwrap{display:block;text-align:right;}
.eqa .totwrap>table.tot{display:inline-table;text-align:left;}
.eqa .alert{display:block;}
.eqa .alert>b,.eqa .alert>span{display:block;}
/* .meta: approved layout is a 2-up grid of .mrow. The table model cannot reproduce a
   2-up wrap of N children, so the engine fallback is a single-column stack, which keeps
   every label/value pair intact and only makes the panel taller. */
.eqa .meta{display:block;}
.eqa .meta .mrow:nth-child(2){border-top:.4pt solid #e4e7ea;}
/* Heading keep-with-next: this engine ignores page-break-after:avoid but honours
   page-break-inside:avoid, so short semantic groups are protected as whole blocks. */
.eqa .sec.scope-sec{page-break-inside:avoid;}
.eqa .annex .spec{page-break-inside:avoid;}

/* 3. Chrome re-assertion of the approved layout */
@supports (display:grid){
.eqa .sec.scope-sec{page-break-inside:auto;}
.eqa .annex .spec{page-break-inside:auto;break-inside:auto;}
.eqa .meta{display:grid;grid-template-columns:1fr 1fr;gap:0 12mm;}
.eqa .meta .mrow:nth-child(2){border-top:0;}
.eqa .mast{display:flex;align-items:flex-start;justify-content:space-between;gap:8mm;width:auto;}
.eqa .mast-l{display:block;flex:0 0 52mm;width:auto;}
.eqa .mast-r{display:block;flex:1 1 auto;text-align:right;}
.eqa .mrow{display:grid;grid-template-columns:auto 1fr;align-items:baseline;column-gap:6mm;width:auto;}
.eqa .mrow>span{display:inline;padding-right:0;}
.eqa .mrow>b{display:inline;width:auto;}
.eqa .gr2{display:grid;grid-template-columns:1fr 1fr;gap:0 6mm;width:auto;}
.eqa .gr2>div{display:block;}
.eqa .gr2>div:first-child{padding-right:0;}
.eqa .gr2>div+div{padding-left:0;}
.eqa .kv{display:flex;gap:3mm;width:auto;}
.eqa .kv>span{display:block;flex:0 0 22mm;width:auto;padding-right:0;}
.eqa .kv>b{display:block;flex:1 1 auto;}
.eqa .totwrap{display:flex;justify-content:flex-end;text-align:left;}
.eqa .totwrap>table.tot{display:table;}
.eqa .alert{display:flex;flex-direction:column;gap:.6mm;}
.eqa .alert>b,.eqa .alert>span{display:block;}
}


/* S-BEAUTIFY 2026-08-16 | page-1 vertical compaction. Presentation values only:
   contact-block leading, masthead padding/margin under the rule, and the title
   margins. No structural, engine-compatibility or layout-model rule is edited,
   and no company information is removed. */
.eqa .entl{line-height:1.18;}
.eqa .mast{padding-bottom:2.2mm;margin-bottom:2.8mm;}
.eqa .doctitle{margin:.5mm 0 3mm 0;}


/* S12 | DYNAMIC COMMERCIAL VALUES: BOLD VALUE WEIGHT --------------------
   Visual ownership rule: a value typed into the quotation by the salesperson
   is bold; static labels, narrative and contractual wording stay regular.
   Commercial Conditions already complies through .eqa .kv b (Delivery,
   Validity, Warranty, Currency, Taxation) with labels held light by
   .eqa .kv span, so those rules are retained untouched.
   Payment Terms was the one remaining commercial term whose value is a
   direct quotation field (doc.custom_payment_terms) yet printed at regular
   weight. The whole field value is bolded as a single unit -- no parsing,
   no partial emphasis of percentages or phrases.
   Scope is deliberate and narrow: the child combinator binds this to the
   direct .rt of .sec.payment-sec only, so Scope Included
   (.eqa .sec.scope-sec > .rt) and Contractual Terms
   (.eqa .sec.tc > .rt.small) keep regular-weight bodies. The PAYMENT TERMS
   heading is .sh and is not touched. Weight is the only declaration:
   font-size, colour, line-height, margins and page-break rules unchanged. */
.eqa .sec.payment-sec > .rt{font-weight:700;}


/* S13 | PAGE-1 METADATA PANEL: TWO-COLUMN TABLE MODEL ---------------------
   Restores the approved reference layout in the real customer PDF. The base
   .meta/.mrow grid rules and their WK-COMPAT fallbacks are left in place but
   are now inert, because the panel no longer emits .meta markup; no existing
   rule is edited. Colours are literals rather than var(), since wkhtmltopdf
   does not implement custom properties -- these are the same values the
   WK-COMPAT layer already pins for this panel: rule #c2c6ca, hairline
   #e4e7ea, label #6b7075, value #141414.
   Five fixed columns: label 19.5% + value 27.5% | 6% gutter | label 19.5% +
   value 27.5%. Each half is 47% of the panel, so the halves are equal and
   the gutter reproduces the former 12mm grid gap. Values are right aligned
   inside their own half.
   Rules are declared in px, not sub-point: this engine floors border widths
   to whole device pixels, so the previous .4pt/.7pt hairlines resolved to
   zero and no rule was drawn in the customer PDF at all. 1px is the thinnest
   width it will actually paint.
   Both cells of a row carry the value font-size so they share one line box
   strut; the label is shrunk on an inner span, which keeps label and value
   on a common baseline. */
.eqa .metawrap{margin-bottom:4.5mm;break-inside:avoid;page-break-inside:avoid;}
.eqa table.metat{width:100%;table-layout:fixed;border-collapse:collapse;
  border-top:1px solid #c2c6ca;border-bottom:1px solid #c2c6ca;}
.eqa table.metat td{padding:1.5mm 0 1.7mm 0;border-bottom:1px solid #e4e7ea;
  font-size:9.2pt;line-height:1.2;vertical-align:top;color:#141414;background:none;}
.eqa table.metat tr.mlast td{border-bottom:0;padding-bottom:0;}
.eqa table.metat td.mc1,.eqa table.metat td.mc4{width:19.5%;text-align:left;}
.eqa table.metat td.mc2,.eqa table.metat td.mc5{width:27.5%;font-weight:700;
  text-align:right;}
.eqa table.metat td.mc3{width:6%;}
.eqa table.metat span.mlbl{font-size:7.8pt;font-weight:400;letter-spacing:.07em;
  text-transform:uppercase;color:#6b7075;white-space:nowrap;}

/* ===== WK-COMPAT | S14 SECTION-HEADING HAIRLINE RESTORATION (append-only) =====
   Defect measured in the production wkhtmltopdf PDF, not inferred from CSS:
   the approved heading rule .eqa .sh{border-bottom:.7pt solid #c2c6ca} is
   never painted. This engine lays out and rasterises border widths in whole
   96dpi device pixels, so .7pt (= .933px) floors to zero; it then emits either
   a zero-height fill rect or no fill call at all. Baseline for 00073: 0 of 9
   heading rules painted across all 3 pages.
   Fix: restate the SAME rule at the smallest width this engine draws
   reliably, 1px (= .75pt at 96dpi). That width is already proven in this
   document by the page-1 metadata table hairlines, which are declared in px
   and do paint. Width is the only property that changes. The colour #c2c6ca
   is the literal value of var(--rule) already restated by the WK-COMPAT
   colour layer above, the style stays solid, and font-size, font-weight,
   letter-spacing, text-transform, padding-bottom and margin-bottom are all
   left untouched. No box, no background, no new element, no extra markup.
   Applies to the whole existing .sh family so the headings keep one visual
   language: Addressed To, Subject, Transmittal, Prepared By, Priced Schedule,
   Scope Included, Commercial Conditions, Payment Terms, Contractual Terms and
   Annexure A. .spec-sh is deliberately excluded: it carries no rule by design. */
.eqa .sh{border-bottom:1px solid #c2c6ca;}

/* ===== S15 | PAGE-1 VERTICAL RHYTHM (append-only, page-1 elements only) =====
   Page 1 read loose in the customer PDF. Vertical space only -- no font size,
   weight, tracking, colour, border, logo or structural change.
   Scope: every selector below resolves exclusively inside the first .pg block.
   .mast, .doctitle, .metawrap and table.metat exist only on page 1, and
   ".metawrap + .sec" is the Addressed To section alone (adjacent sibling of the
   page-1 metadata wrapper). The two .pg blocks are separated by the existing
   hard break .eqa .pg + .pg, so shortening page 1 cannot reflow anything onto
   or off pages 2+.
   Root cause of the oversized metadata rows: Frappe's own print stylesheet
   ships ".print-format td,.print-format th{padding:10px !important}". That
   !important beat every padding this format declared for table.metat td, so
   the authored 1.5mm/1.7mm was inert and each row carried a forced 20px
   (15pt) of vertical padding. Measured proof: dropping the format padding to
   0 and line-height to 1 moved the row height by only 1.5pt. The padding below
   is therefore declared !important at higher specificity (0,3,1 vs 0,1,1) so
   the format wins for this one page-1 table and nothing else. Row padding
   stays symmetric top/bottom -- the inert tr.mlast padding-bottom:0 is
   deliberately not revived, so the two-column panel keeps even rows. Its
   border-bottom:0 still applies, so the last row still shows only the table
   rule. Column widths, alignment, label/value typography and the 1px
   hairlines are untouched.
   .mast padding-bottom stays 2.2mm, so the logo, the contact block and the
   navy rule keep their exact positions and the masthead does not move toward
   the physical top edge. Title typography (16pt / 700 / 1.2) untouched.
   Baseline -> new, page 1: masthead rule to metadata top 34.5pt; metadata row
   height 26.25pt; metadata bottom to ADDRESSED TO 27.75pt; ADDRESSED TO to
   SUBJECT 43.5pt. */
.eqa .mast{margin-bottom:2.2mm;}
.eqa .doctitle{margin:.3mm 0 2.4mm 0;}
.eqa table.metat td{padding:1.5mm 0 1.6mm 0 !important;}
.eqa .metawrap{margin-bottom:3.6mm;}
.eqa .metawrap + .sec{margin-bottom:2.6mm;}

/* ═════ WK-COMPAT | S15  PAGE-1 FONT HIERARCHY (append-only) ═════
   SCOPE. Every rule is bound to the first .pg only. Verified against the live
   markup: .eqa has exactly two element children, both .pg, and the page-1 .pg is
   the first, so .eqa > .pg:first-child resolves to page 1 alone. The combinator
   was proved in THIS engine by a throwaway probe, not assumed: setting
   .eqa > .pg:first-child .sh{font-size:14pt} printed the four page-1 headings at
   14.25pt in the real wkhtmltopdf PDF while the five page-2/3 headings stayed at
   8.25pt. Pages 2+ are therefore unreachable from this block, and that was then
   confirmed byte-for-byte: every page-2+ content stream is unchanged.

   SIZES. This engine lays out at 96dpi and floors every font-size and line-height
   to a whole device pixel, so the printed size is round(pt * 4/3) * 0.75 and many
   pt values are indistinguishable. Each value below is the SMALLEST value inside
   its approved band that the engine actually prints larger than the current one.
   8.5pt was tried first for the headings and rejected: it floors to the same 11px
   as 8.4pt and prints identically.

   Only font-size changes, plus one line-height on the transmittal body. No
   structure, colour, weight, letter-spacing, margin, padding, border or
   alignment is touched anywhere.

   NOT CHANGED, deliberately:
   - .mast has NO page-1 offset. A negative margin-top was tested at -1, -2, -3
     and -4mm and rejected on measured evidence: this engine clamps the logo image
     to the body content-box top (it stayed at 782.75pt at every offset) while the
     navy rule and the text did move, so the logo-to-rule gap collapsed from 6pt
     to 0.75pt at -2mm and the rule crossed the logo at -3mm; and the header band
     paints an opaque white rectangle down to exactly the content-box top, so the
     first address line was shaved at -1mm and dropped from the PDF at -4mm.
   - .pn customer name stays 11pt. The approved band is 11-11.5pt and both ends
     floor to 15px, so 11pt already prints the largest size in the band (11.25pt).
   - .mlbl metadata labels stay 7.8pt (print 7.5pt), inside the keep band.
   - .entl contact block, .logo, navy rule, subject band, all weights, tracking,
     colours, margins and padding: untouched.
   ─────────────────────────────────────────────────────────────────────────── */

/* Commercial Quotation title: 16pt -> 17pt (21px -> 23px, prints 15.75 -> 17.25pt) */
.eqa > .pg:first-child .doctitle{font-size:17pt;}

/* Metadata panel: 9.2pt -> 9.5pt (12px -> 13px, prints 9 -> 9.75pt).
   Applied to EVERY cell, not only the value cells. The label cells contain nothing
   but <span class="mlbl">, which carries its own 7.8pt, so the labels print
   unchanged at 7.5pt; but raising the cell font-size keeps every cell line box at
   the same 15.6px. Restricting this to td.mc2/td.mc5 was tried first and rejected:
   it left the label cells on a 14.4px line box and split the label and value
   baselines by 0.7pt, breaking the row alignment of the approved two-column
   panel. Column widths, padding, borders and the 700 weight on the value cells
   are untouched. */
.eqa > .pg:first-child table.metat td{font-size:9.5pt;}

/* Page-1 headings ADDRESSED TO / SUBJECT / TRANSMITTAL / PREPARED BY:
   8.4pt -> 9pt (11px -> 12px, prints 8.25 -> 9pt). */
.eqa > .pg:first-child .sh{font-size:9pt;}

/* Subject value: 10pt -> 10.5pt (13px -> 14px, prints 9.75 -> 10.5pt). */
.eqa > .pg:first-child .subj{font-size:10.5pt;}

/* Transmittal body: 9pt -> 9.5pt (prints 9 -> 9.75pt). Leading is declared 1.31,
   not 1.3, because the engine floors the computed line box: 1.3 x 13px = 16.9px
   floors to 16px and printed a 1.23 ratio, tighter than approved, whereas 1.31 x
   13px = 17.03px floors to 17px and prints 12.75pt, a 1.308 ratio. Only the three
   DIRECT p children of a page-1 .sec are selected; the Contractual Terms
   paragraphs on page 2 sit inside .rt and are grandchildren, so this combinator
   cannot reach them. */
.eqa > .pg:first-child .sec > p{font-size:9.5pt;line-height:1.31;}

/* Prepared By name: 9pt -> 9.5pt (prints 9 -> 9.75pt). The company line beneath
   carries .pf and is pinned back to its approved 8.4pt at higher specificity so
   append order cannot promote it. */
.eqa > .pg:first-child .pl{font-size:9.5pt;}
.eqa > .pg:first-child .pl.pf{font-size:8.4pt;}
